sys_script_include.script:
var DirectoryMemberAPI = Class.create();
DirectoryMemberAPI.CONSTANTS = {
    API_CONFIG: {
        GET_MEMBER_DETAILS: {
            path: "/admin/directory/v1/groups/${groupKey}/members/${memberKey}",
            httpMethod: "GET",
            pathParams: ["memberKey", "userKey"]
        },
        LIST_MEMBERS: {
            path: "/admin/directory/v1/groups/${groupKey}/members",
            httpMethod: "GET",
            pathParams: ["memberKey"]
        },
        INSERT: {
            path: "/admin/directory/v1/groups/${groupKey}/members",
            httpMethod: "POST",
            pathParams: ["groupKey"],
            content: {
                kind: {
                    required: true,
                    defaultValue: "admin#directory#member"
                },
                email: {
                    required: true
                },
                role: {
                    required: true,
                    enum: ["MANAGER", "MEMBER", "OWNER"]
                },
                type: {
                    required: true,
                    enum: ["CUSTOMER", "EXTERNAL", "GROUP", "USER"]
                },
                delivery_settings: {
                    required: true,
                    enum: ["ALL_MAIL", "DAILY", "DIGEST", "DISABLED", "NONE"]
                }
            }
        },
        DELETE_MEMBER: {
            path: "/admin/directory/v1/groups/${groupKey}/members/${memberKey}",
            httpMethod: "DELETE",
            pathParams: ["memberKey", "userKey"]
        },
    }
};
DirectoryMemberAPI.prototype = Object.extend(new x_neyu_google_nyu.RestUtil(), {
    initialize: function() {
        this.oauthProvider = "8491b701ebcf7a105c06fcffcad0cda8";
        this.providerProfile = "3b683f45ebcf7a105c06fcffcad0cd99";
        this.credential = gs.getProperty("x_neyu_google_nyu.directory.api.credential.id");
        this.aliasId = "1249fca42b94c3508a69f0dcce91bf0f";
    },


    /**
     * Retrieves details for a specific member within a Google Group.
     * * This method validates credentials, ensures a valid OAuth token, and executes 
     * the request via the Google Directories API.
     * * @param {string} groupKey - The group's email address, alias, or unique group ID.
     * @param {string} memberKey - The member's email address or unique member ID.
     * * @returns {Object} Standardized Response Object
     * @returns {boolean} return.error - True if a validation or API error occurred.
     * @returns {number} return.status - The HTTP status code (e.g., 200, 404, 500).
     * @returns {string} return.errorMessage - Description of the error (null if successful).
     * @returns {string} return.responseBody - The raw JSON string from the API. 
     * **Note:** Must be parsed using `JSON.parse()` before use.
     * * @example
     * const result = utils.getMemberDetails('hr-group@company.com', 'user@company.com');
     * if (!result.error) {
     * const data = JSON.parse(result.responseBody);
     * gs.info("Member Role: " + data.role);
     * } else {
     * gs.error("Failed to fetch member: " + result.errorMessage);
     * }
     */
    getMemberDetails: function(groupKey, memberKey) {
        gs.info("[getMemberDetails]\nGroup Key: {0}\nMemberKey: {1}",
            groupKey, memberKey);

        if (!groupKey || !memberKey) {
            return {
                error: true,
                errorMessage: "groupKey and memberKey are required"
            };
        }

        this.ensureToken(this.credential, this.oauthProvider, this.providerProfile);

        const pathParams = {
            groupKey: groupKey,
            memberKey: memberKey
        };
        const config = DirectoryMemberAPI.CONSTANTS.API_CONFIG.GET_MEMBER_DETAILS;
        const requestConfig = {
            ...config,
            pathParams,
            aliasId: this.aliasId
        };

        const response = this.execute(requestConfig, "getMemberDetails");

        if (response.error) {
            gs.error("[getMemberDetails] There was an error returned from the " +
                "Google Directories API. \nError: " + response.errorMessage);
        }

        return {
            ...response
        };
    },

    /**
     * Retrieves a list of all members within a specified Google Group.
     * * This method handles the OAuth token check and executes the request against 
     * the Google Directories API. It includes specialized logging that captures 
     * non-500 errors for debugging.
     * * @param {string} groupKey - The group's email address, alias, or unique group ID.
     * * @returns {Object} Standardized Response Object
     * @returns {boolean} return.error - True if a validation or API error occurred.
     * @returns {number} return.status - The HTTP status code (e.g., 200, 403, 404).
     * @returns {string} return.errorMessage - Description of the error (null if successful).
     * @returns {string} return.responseBody - The raw JSON string containing the list of members.
     * **Note:** Must be parsed using `JSON.parse()` before use.
     * * @example
     * const result = utils.listMembers('it-support@company.com');
     * if (!result.error) {
     * const data = JSON.parse(result.responseBody);
     * gs.info("Total members found: " + data.members.length);
     * }
     */
    listMembers: function(groupKey) {
        gs.info("[listMembers]\nGroup Key: {0}", groupKey);

        if (!groupKey) {
            return {
                error: true,
                errorMessage: "groupKey is required"
            };
        }

        this.ensureToken(this.credential, this.oauthProvider, this.providerProfile);

        const pathParams = {
            groupKey: groupKey
        };
        const config = DirectoryMemberAPI.CONSTANTS.API_CONFIG.LIST_MEMBERS;
        const requestConfig = {
            ...config,
            pathParams,
            aliasId: this.aliasId
        };

        const response = this.execute(requestConfig, "listMembers");

        if (response.error && response?.status != 500) {
            gs.error("[listMembers] There was an error returned from the " +
                "Google Directories API. \nResponse: " + JSON.stringify(response));
        }

        return {
            ...response
        };
    },

    /**
     * Adds (inserts) a new member into a specified Google Group.
     * * This method performs pre-flight validation against a specification schema, 
     * ensures OAuth connectivity, and maps input parameters to the Google Directory API format.
     * * @param {string} groupKey - The group's email address, alias, or unique group ID.
     * @param {string} userId - The email address or ID of the user to be added.
     * @param {Object} [options={}] - Optional configuration for the new member.
     * @param {string} [options.kind="admin#directory#member"] - The type of the resource.
     * @param {string} [options.type="USER"] - The member type (e.g., 'USER', 'GROUP', 'CUSTOMER').
     * @param {string} [options.role="MEMBER"] - The member's role (e.g., 'MEMBER', 'OWNER', 'MANAGER').
     * @param {string} [options.deliverySettings="ALL_MAIL"] - Email delivery settings.
     * * @returns {Object} Standardized Response Object
     * @returns {boolean} return.error - True if validation fails or the API returns an error.
     * @returns {number} return.status - The HTTP status code (e.g., 200, 400, 403).
     * @returns {string} return.errorMessage - A concatenated string of validation errors or API errors.
     * @returns {string} return.responseBody - The raw JSON string of the created member record. 
     * **Note:** Must be parsed using `JSON.parse()` before use.
     * * @example
     * // Adding a member with default settings
     * const result = utils.insert('support@company.com', 'new.user@company.com');
     * * // Adding a manager with specific delivery settings
     * const result = utils.insert('support@company.com', 'lead@company.com', {
     * role: 'MANAGER',
     * deliverySettings: 'DIGEST'
     * });
     */
    insert: function(groupKey, userId, {
        kind = "admin#directory#member",
        type = "USER",
        role = "MEMBER",
        deliverySettings = "ALL_MAIL"
    } = {}) {
        gs.info("[addMember]\ngroupKey: " + groupKey +
            "\nuserId: " + userId +
            "\nkind: " + kind +
            "\ntype: " + type +
            "\nrole: " + role +
            "\ndeliverySettings: " + deliverySettings);

        if (!groupKey || !userId || !kind || !type || !role || !deliverySettings) {
            return {
                error: true,
                errorMessage: "There are empty required parameters"
            };
        }

        this.ensureToken(this.credential, this.oauthProvider, this.providerProfile);

        const config = DirectoryMemberAPI.CONSTANTS.API_CONFIG.INSERT;
        // get the content specification so we can validate the inputs
        const {
            content: spec
        } = config;
        const content = {
            email: userId,
            kind: kind,
            type: type,
            role: role,
            delivery_settings: deliverySettings
        };

        // validate the inputs
        if ((errors = this.validateContent(spec, content))) {
            const errorMessage = Object.entries(errors)
                .map(([k, v]) => v?.error)
                .join("\n");
            return {
                error: true,
                status: 400,
                errorMessage: errorMessage
            };
        }

        const pathParams = {
            groupKey: groupKey
        };
        const requestConfig = {
            ...config,
            pathParams,
            content: JSON.stringify(content),
            aliasId: this.aliasId
        };

        const response = this.execute(requestConfig, "insert");

        if (response.error && response?.status != 500) {
            gs.error(`[insert] There was an error returned from the` +
                `Google Directories API.\nResponse: ${JSON.stringify(response)}`);
        }

        return {
            ...response
        };
    },

    /**
     * Removes a specific member within a Google Group.
     * * This method validates credentials, ensures a valid OAuth token, and executes 
     * the request via the Google Directories API.
     * * @param {string} groupKey - The group's email address, alias, or unique group ID.
     * @param {string} memberKey - The member's email address or unique member ID.
     * * @returns {Object} Standardized Response Object
     * @returns {boolean} return.error - True if a validation or API error occurred.
     * @returns {number} return.status - The HTTP status code (e.g., 200, 404, 500).
     * @returns {string} return.errorMessage - Description of the error (null if successful).
     * @returns {string} return.responseBody - The raw JSON string from the API. 
     * **Note:** Must be parsed using `JSON.parse()` before use.
     * * @example
     * const result = utils.getMemberDetails('hr-group@company.com', 'user@company.com');
     * if (!result.error) {
     * gs.info("Successful status: " + result.status);
     * } else {
     * gs.error("Failed to fetch member: " + result.errorMessage);
     * }
     */
    deleteMember: function(groupKey, memberKey) {
        gs.info("[deleteMember]\nGroup Key: {0}\nMemberKey: {1}",
            groupKey, memberKey);

        if (!groupKey || !memberKey) {
            return {
                error: true,
                errorMessage: "groupKey and memberKey are required"
            };
        }

        this.ensureToken(this.credential, this.oauthProvider, this.providerProfile);

        const pathParams = {
            groupKey: groupKey,
            memberKey: memberKey
        };
        const config = DirectoryMemberAPI.CONSTANTS.API_CONFIG.DELETE_MEMBER;
        const requestConfig = {
            ...config,
            pathParams,
            aliasId: this.aliasId
        };

        const response = this.execute(requestConfig, "deleteMember");

        if (response.error) {
            gs.error("[deleteMember] There was an error returned from the " +
                "Google Directories API. \nError: " + response.errorMessage);
        }

        return {
            ...response
        };
    },


    type: 'DirectoryMemberAPI'
});
